const root=$json.body; if(root?.object!=='page') return [];
const out=[], seen=new Set();
for(const entry of root.entry||[]) for(const e of entry.messaging||[]){
if(!e.message || e.message.is_echo || !e.message.mid || !e.sender?.id || seen.has(e.message.mid))continue;
seen.add(e.message.mid); const text=e.message.text;
if(typeof text!=='string'||!text.trim()||text.length>2000)continue;
out.push({json:{page_id:String(entry.id),sender_id:String(e.sender.id),message_id:e.message.mid,message:text.trim(),session_key:'facebook:'+entry.id+':'+e.sender.id,received_at:new Date().toISOString()}});
}return out;

const doc = $json;
const parts = [];

function extract(value) {
  if (!value || typeof value !== 'object') return;

  if (value.textRun?.content) {
    parts.push(value.textRun.content);
  }

  for (const [key, child] of Object.entries(value)) {
    if (key === 'textRun') continue;

    if (Array.isArray(child)) {
      child.forEach(extract);
    } else if (child && typeof child === 'object') {
      extract(child);
    }
  }
}

if (typeof doc.content === 'string') {
  parts.push(doc.content);
} else {
  extract(doc);
}

const content = parts.join('').trim();

return {
  json: {
    content,
    kb_ok: content.length > 50,
    diagnostic: doc.error
      ? 'Google Docs retrieval failed'
      : content
        ? 'Document text extracted'
        : 'No document text found'
  }
};

const event = $('Normalize Event').item.json;
const question = String(event.message ?? '');

const normalize = (text) => text
  .normalize('NFKC')
  .toLowerCase()
  .replace(/[\p{P}\p{S}]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const isTaglish = /\b(po|ba|saan|kayo|ano|magkano|ngayon|puwede|pwede)\b/i
  .test(question);

let result;
try {
  const raw = String($json.output ?? '').trim();
  result = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/gi, ''));
} catch {
  result = null;
}

const valid = ['answer', 'clarify', 'handoff'].includes(result?.action)
  && typeof result.reply === 'string'
  && Boolean(normalize(result.reply));

const isEcho = valid && normalize(result.reply) === normalize(question);

if (!valid || isEcho) {
  result = {
    action: 'handoff',
    reply: isTaglish
      ? 'Sorry po, hindi ko ma-confirm ang details ngayon. Our team can help.'
      : 'Sorry, I couldn’t confirm the details right now. Our team can help.',
    reason: isEcho ? 'echoed_customer_message' : 'knowledge_or_model_failure',
  };
}

return {
  json: {
    ...event,
    action: result.action,
    reply: result.reply.trim().slice(0, 1500),
    reason: typeof result.reason === 'string' ? result.reason : '',
  },
};

const result = $('Validate Reply').item.json;
const saved = Number($json.updates?.updatedRows ?? 0) > 0;

let reply = result.reply;

if (result.action === 'handoff' && !saved) {
  reply = 'I could not save your inquiry for staff review. Please contact the cafe directly through this Page.';
}

return {
  json: {
    ...result,
    reply,
    record_saved: saved,
  },
};

