}
const cfg=$('S01 Staff Decision Settings').item.json;const H=["reservation_id", "created_at", "session_key", "page_id", "sender_id", "guest_name", "phone", "date", "time", "party_size", "status", "source_message_id", "last_customer_at", "staff_note", "decided_at", "notification_status", "notification_message_id", "email", "dining_minutes", "calendar_event_id", "calendar_status", "email_status", "email_message_id", "calendar_event_link", "integration_error"];
