if(v[10]==='approved'&&(!v[17]||cfg.calendar_id.startsWith('REPLACE')))throw new Error('Approved requests require a customer email and configured calendar ID. Fill email in column R for older pending rows; set S01 CALENDAR_ID once.');
if(v[17]&&(!/^[^\s@\r\n]+@[^\s@\r\n]+\.[^\s@\r\n]+$/.test(v[17])))throw new Error('Invalid stored email; correct column R.');
