const body = $json.body;
const valid = body?.event_type === 'submission'
  && body.form_id === 'YOUR_YOUFORM_SLUG'
  && /^[A-Za-z0-9_-]{1,100}$/.test(body.submission_id ?? '')
  && Array.isArray(body.fields);
if (!valid) throw new Error('Expected a completed Youform v2 submission from YOUR_YOUFORM_SLUG.');
const submission = body.submission_id;
const reference = 'AR-YF-' + [...submission].map(char => char.charCodeAt(0).toString(16)).join('').toUpperCase();
const hidden = body.fields.find(field => field.type === 'hidden' && (field.question === 'booking_ref' || field.id === 'booking_ref' || field.name === 'booking_ref'));
const rawToken = hidden?.answer ?? body.answers?.booking_ref ?? '';
const token = /^[a-f0-9]{48}$/.test(rawToken) ? rawToken : '';
return {json:{sheet_id:"YOUR_LOG_SPREADSHEET_ID", submission, reference, token, fields:body.fields}};

const headers = [
  'reservation_id', 'created_at', 'session_key', 'page_id', 'sender_id',
  'guest_name', 'phone', 'date', 'time', 'party_size', 'status',
  'source_message_id', 'last_customer_at', 'staff_note', 'decided_at',
  'notification_status', 'notification_message_id', 'email', 'dining_minutes',
  'calendar_event_id', 'calendar_status', 'email_status', 'email_message_id',
  'calendar_event_link', 'integration_error',
];

const request = $('Y02 Read Submission').item.json;
const attempt = $('Get Attempt Row').item.json;
const rows = $json.values;

if (
  $json.error ||
  !Array.isArray(rows) ||
  rows.length >= 10001 ||
  !headers.every((header, i) => rows[0]?.[i] === header)
) {
  throw new Error('Could not verify Reservations A:Y headers or queue size.');
}

const reservations = rows.slice(1);
const result = {
  sheet_id: request.sheet_id,
  reference: request.reference,
  duplicate: reservations.some(row => row[0] === request.reference),
};

if (result.duplicate) {
  return { json: { ...result, write: false, status: 200 } };
}

function reject(message, rejection = '') {
  return { json: { ...result, write: false, status: 422, message, rejection } };
}

function answer(label) {
  const field = request.fields.find(field =>
    String(field.question ?? '').trim().toLowerCase()
      .replace(/[:?*]+$/, '').trim() === label
  );
  const value = field?.answer;
  return typeof value === 'string' || typeof value === 'number'
    ? String(value).trim()
    : '';
}

function normalizeName(value) {
  return String(value ?? '').normalize('NFKC').trim()
    .replace(/\s+/g, ' ').toLowerCase();
}

function normalizeEmail(value) {
  return String(value ?? '').trim().toLowerCase();
}

function normalizePhone(value) {
  return String(value ?? '').replace(/[\s()-]/g, '').replace(/^\+63/, '0');
}

const rawDate = answer('reservation date');
const isoDate = /^(\d{4})-(\d{2})-(\d{2})(?:T00:00:00(?:\.0+)?Z)?$/.exec(rawDate);
const usDate = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(rawDate);

let date = '';
if (isoDate) {
  date = isoDate.slice(1).join('-');
} else if (usDate) {
  const [, month, day, year] = usDate;
  date = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
}

const calendarDay = new Date(`${date}T00:00:00Z`);
if (
  !date ||
  !Number.isFinite(calendarDay.getTime()) ||
  calendarDay.toISOString().slice(0, 10) !== date
) {
  return reject('Select a valid reservation date.');
}

const period = answer('am or pm').toUpperCase();
const clock = /^(0?[1-9]|1[0-2]):([0-5]\d)$/.exec(answer('arrival time'));

if (!clock || !['AM', 'PM'].includes(period)) {
  return reject('Select a valid arrival time and AM or PM.', 'format');
}

const hour = Number(clock[1]) % 12 + (period === 'PM' ? 12 : 0);
const minute = Number(clock[2]);
const time = `${String(hour).padStart(2, '0')}:${clock[2]}`;

const guests = answer('number of guests');
const name = answer('guest name');
const phone = normalizePhone(answer('mobile number'));
const email = answer('email address');

if (!/^[1-8]$/.test(guests)) {
  return reject('Party size must be from 1 through 8.');
}
if (!name || name.length > 100 || /[\r\n]/.test(name)) {
  return reject('Enter a valid guest name.');
}
if (!/^09\d{9}$/.test(phone)) {
  return reject('Enter a Philippine mobile number.');
}
if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  return reject('Enter a valid email address.');
}

const partySize = Number(guests);
const now = Date.now();
const arrival = Date.parse(`${date}T${time}:00+08:00`);

if (arrival < now + 120 * 60_000 || arrival > now + 30 * 86_400_000) {
  return reject('Choose an arrival at least two hours away and within 30 days.', 'notice');
}

const sunday = calendarDay.getUTCDay() === 0;
const opensAt = (sunday ? 14 : 9) * 60;
const closesAt = (sunday ? 20 : 22) * 60;
const diningMinutes = 90;
const arrivalMinutes = hour * 60 + minute;

if (arrivalMinutes < opensAt || arrivalMinutes + diningMinutes > closesAt) {
  return reject(
    'Choose an arrival during cafe hours that allows 90 minutes before closing.',
    sunday ? 'sunday_hours' : 'weekday_hours',
  );
}

const nameKey = normalizeName(name);
const emailKey = normalizeEmail(email);

const matches = reservations
  .map((row, index) => ({
    row,
    rowNumber: index + 2,
    status: String(row[10] ?? '').trim().toLowerCase(),
  }))
  .filter(({ row, status }) =>
    ['pending', 'approved'].includes(status) &&
    String(row[7] ?? '').trim() === date &&
    normalizeName(row[5]) === nameKey &&
    normalizeEmail(row[17]) === emailKey &&
    normalizePhone(row[6]) === phone
  );

if (matches.length > 1) {
  return reject('Multiple active reservations match these details. Please contact Arya’s Cafe for help.');
}

if (matches.length === 1) {
  const { row, rowNumber, status } = matches[0];
  const timeChanged = String(row[8] ?? '').trim().padStart(5, '0') !== time;
  const partySizeChanged = Number(row[9]) !== partySize;
  const canUpdate = attempt.newAttempt === true &&
    status === 'pending' &&
    (timeChanged || partySizeChanged);

  return {
    json: {
      ...result,
      reference: row[0],
      duplicate: true,
      duplicateBooking: true,
      write: canUpdate,
      status: 200,
      ...(canUpdate ? {
        updateRow: rowNumber,
        reservationValues: [time, partySize],
      } : {}),
    },
  };
}

return {
  json: {
    ...result,
    write: true,
    reservationValues: [
      request.reference, new Date(now).toISOString(), `youform:${request.submission}`,
      '', '', name, phone, date, time, partySize, 'pending', request.submission,
      '', '', '', 'not_applicable', '', email, diningMinutes, '',
      'not_created', 'not_sent', '', '', '',
    ],
  },
};

const request = $('Y04 Validate and Prepare Row').item.json;
const updated = Boolean(request.updateRow);
const count = updated ? $json.updatedRows : $json.updates?.updatedRows;
if ($json.error || count !== 1) throw new Error('Reservation write was not confirmed.');
const saved = $('Link New Reservation to Messenger?').item.json;
const linked = !updated && $('Get Attempt Row').item.json.token
  ? $('Attach Messenger Recipient').item.json.reservationValues
  : saved.reservationValues;
return {json:{
  reference:request.reference, status:updated ? 200 : 201, duplicate:updated, updated,
  pendingReceipt: !updated && linked ? {date:linked[7],time:linked[8],guests:linked[9],linked:Boolean(linked[3] && linked[4])} : null
}};

const event = $('Normalize Event').item.json;
const token = require('crypto').randomBytes(24).toString('hex');
const taglish = /\b(?:po|ba|pwede|puwede|gusto|ng|mesa|mag[\s-]*book|(?:mag[\s-]*)?pa[\s-]*(?:pa[\s-]*)?reserve|mag[\s-]*reserve)\b/i.test(event.message);
const received = new Date(event.received_at).toISOString();
return {json:{sheet_id:"YOUR_LOG_SPREADSHEET_ID",token,taglish,values:[token,event.page_id,event.sender_id,received,taglish?'taglish':'english']}};

const request = $('Y02 Read Submission').item.json;
const rows = $json.values;
if (!Array.isArray(rows) || rows[0]?.join('|') !== 'submission_id|received_at|reference|status|notification') throw new Error('Check ReservationAttempts A:E headers.');
const index = rows.findIndex(row => row[0] === request.submission);
return {json:{...request, newAttempt:index < 0, attemptRow:index+1, values:[request.submission,new Date().toISOString(),request.reference,'received','not_attempted']}};

const p = $('Prepare Attempt Record').item.json;
if (!p.newAttempt) return {json:p};
const match = /!A(\d+):E\d+$/.exec($json.updates?.updatedRange ?? '');
if (!match || $json.updates?.updatedRows !== 1) throw new Error('Reservation attempt write not verified.');
return {json:{...p,attemptRow:Number(match[1])}};

const result = $json;
const attempt = $('Get Attempt Row').item.json;
const invalid = result.status === 422;
const invalidTimeslot = invalid && Boolean(result.rejection);

let outcome = 'pending';

if (result.updated) {
  outcome = 'updated_booking';
