  json: {
    ...result,
    sheet_id: attempt.sheet_id,
    attemptRow: attempt.attemptRow,
    token: attempt.token,
    outcome,
    lookup,
    notification,
    preserve: (invalid || result.duplicate) && !attempt.newAttempt && !result.updated,
  },
};

